<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';require_once __DIR__.'/../config/config.php';if(session_status()===PHP_SESSION_NONE)session_start();
function back(int $id,string $m,string $t='success'):never{header('Location: /admin/user_view.php?'.http_build_query(['id'=>$id,'message'=>$m,'type'=>$t]));exit;}
$id=filter_input(INPUT_POST,'user_id',FILTER_VALIDATE_INT);$pic=filter_input(INPUT_POST,'pic_num',FILTER_VALIDATE_INT);if(!$id||!$pic)exit('נתונים לא תקינים');if(empty($_SESSION['admin_user_csrf'])||!hash_equals((string)$_SESSION['admin_user_csrf'],(string)($_POST['csrf_token']??'')))back($id,'בקשה לא תקינה','error');
try{$s=$pdo->prepare('SELECT Pic_Name,Main_Pic FROM user_pics WHERE Pic_Num=? AND Id=? LIMIT 1');$s->execute([$pic,$id]);$p=$s->fetch(PDO::FETCH_ASSOC);if(!$p)throw new RuntimeException('התמונה לא נמצאה');$a=(string)($_POST['action']??'');if($a==='set_main'){$pdo->beginTransaction();$pdo->prepare('UPDATE user_pics SET Main_Pic=0 WHERE Id=?')->execute([$id]);$pdo->prepare('UPDATE user_pics SET Main_Pic=1 WHERE Pic_Num=? AND Id=? LIMIT 1')->execute([$pic,$id]);$pdo->commit();back($id,'התמונה הוגדרה כראשית');}if($a==='delete'){$was=(int)$p['Main_Pic']===1;$name=basename((string)$p['Pic_Name']);$pdo->beginTransaction();$pdo->prepare('DELETE FROM user_pics WHERE Pic_Num=? AND Id=? LIMIT 1')->execute([$pic,$id]);if($was){$s=$pdo->prepare('SELECT Pic_Num FROM user_pics WHERE Id=? ORDER BY Pic_Num LIMIT 1');$s->execute([$id]);$next=$s->fetchColumn();if($next)$pdo->prepare('UPDATE user_pics SET Main_Pic=1 WHERE Pic_Num=? AND Id=? LIMIT 1')->execute([(int)$next,$id]);}$pdo->commit();$path=dirname(__DIR__).'/uploads/'.$name;if($name!==''&&is_file($path))@unlink($path);back($id,'התמונה נמחקה');}throw new RuntimeException('פעולה לא מוכרת');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();back($id,$e->getMessage(),'error');}
